describe('JavaScript Alerts Tests', () => {
  it('should confirm the alert dialog', () => {
    cy.visit('https://the-internet.herokuapp.com/javascript_alerts');
    cy.get('#confirmButton').click();
    cy.on('window:confirm', (text) => {
      return true;
    });
    cy.url().should('include', '/javascript_alerts');
    cy.get('#result').should('be.visible');
    cy.url().should('include', '/javascript_alerts');
    cy.get('#result').should('contain', 'You clicked: Ok');
  });

  it('should not change the URL when clicking the button again', () => {
    cy.visit('https://the-internet.herokuapp.com/javascript_alerts');
    cy.get('#confirmButton').click();
    cy.get('#confirmButton').click();
    cy.url().should('include', '/javascript_alerts');
    cy.get('#result').should('be.visible');
    cy.get('#result').should('contain', 'You clicked: Cancel');
  });
});
